use crate::{*,serde_json::{json,Value}};
#[test]fn reference_weather_validates_place_and_persists_before_child(){let mut f=super::weather::controller(json!({}));for(a,v)in[("place.label","Home"),("place.latitude","40"),("place.longitude","-80")]{f=super::weather::controller(json!({"state":f["state"],"event":{"action":a,"value":v}}));}let opened=super::weather::controller(json!({"state":f["state"],"event":{"action":"place.open"}}));assert_eq!(opened["effect"]["service"],"collections.transact");let failed=super::weather::controller(json!({"state":opened["state"],"event":{"action":"place.saved","reply":{"ok":false}}}));assert_eq!(failed["state"]["route"],"place");}
#[test]fn reference_listening_selects_episode_and_does_not_switch_radio_stream(){let mut f=super::listening::controller(json!({}));f["state"]["episodes"]=json!([{"url":"https://audio.example.org/a","title":"Chosen"}]);let played=super::listening::controller(json!({"state":f["state"],"event":{"action":"episode.0"}}));assert_eq!(played["effect"]["args"]["queue"][0]["title"],"Chosen");let mut state=played["state"].clone();state["stream"]=json!("https://audio.example.org/live");state["radio"]=json!({"title":"Old"});let failed=super::listening::controller(json!({"state":state,"event":{"action":"listen.radio.loaded","reply":{"ok":false}}}));assert_eq!(failed["state"]["stream"],"https://audio.example.org/live");assert!(failed["state"]["radio"].is_null());}
fn provider()->Value{maps::provider("demo","Demo","https://tiles.example.org/{z}/{x}/{y}.png","Demo","https://tiles.example.org/license",false,true)}
#[test]fn reference_map_bounds_center_and_uses_cache_before_http(){let mut f=super::tile_map::controller(json!({}),provider());for(a,v)in[("map.latitude","0"),("map.longitude","180"),("map.zoom","2")]{f=super::tile_map::controller(json!({"state":f["state"],"event":{"action":a,"value":v}}),provider());}let f=super::tile_map::controller(json!({"state":f["state"],"event":{"action":"map.open"}}),provider());assert_eq!(f["state"]["x"],0);assert_eq!(f["body"].as_array().unwrap().last().unwrap()["kind"],"map_viewer");let sized=super::tile_map::controller(json!({"state":f["state"],"event":{"action":"map.viewport","value":{"width":640,"height":480}}}),provider());let load=super::tile_map::controller(json!({"state":sized["state"],"event":{"action":"map.load"}}),provider());assert_eq!(load["effect"]["service"],"maps.cache.viewport");}
#[test]fn reference_mail_hides_handles_and_headers_on_account_menu(){let c=super::mail::Config{endpoint:"https://mail.example.org/jmap",provider:"mail",server_account:"account",mailbox:"inbox"};let f=super::mail::controller(json!({"event":{"action":"start"}}),&c);assert_eq!(f["effect"]["service"],"accounts.list");let mut state=f["state"].clone();state["active"]=json!({"account":"secret-opaque-handle"});state["snapshot"]=json!({"items":[{"subject":"private header"}]});let menu=super::mail::controller(json!({"state":state,"event":{"action":"mail.accounts"}}),&c);assert!(menu["state"]["snapshot"].is_null());assert!(!menu["body"].to_string().contains("secret-opaque-handle"));assert!(!menu["body"].to_string().contains("private header"));}
#[test]fn wrap_map_batches_hits_and_network_without_skipping_or_erasing(){let p=provider();let mut f=super::tile_map::controller(json!({}),p.clone());for(a,v)in[("map.latitude","0"),("map.longitude","0"),("map.zoom","2")]{f=super::tile_map::controller(json!({"state":f["state"],"event":{"action":a,"value":v}}),p.clone());}f=super::tile_map::controller(json!({"state":f["state"],"event":{"action":"map.open"}}),p.clone());let f=super::tile_map::controller(json!({"state":f["state"],"event":{"action":"map.coverage","reply":{"ok":true,"value":{"tiles":[{"x":1,"y":1,"value":{"hit":true,"file":"a".repeat(32)}},{"x":2,"y":1,"value":{"hit":false,"request":{"url":"https://tiles.example.org/2/2/1.png","method":"GET","response":"hex","headers":{}}}}]}}}}),p.clone());assert_eq!(f["effect"]["service"],"http.request");assert_eq!(f["state"]["map"]["tiles"].as_array().unwrap().len(),1);let done=super::tile_map::controller(json!({"state":f["state"],"event":{"action":"map.stored","reply":{"ok":true,"value":{"stored":true,"file":"b".repeat(32)}}}}),p.clone());assert_eq!(done["state"]["map"]["tiles"].as_array().unwrap().len(),2);assert_eq!(done["state"]["loading"],false);let moved=super::tile_map::controller(json!({"state":done["state"],"event":{"action":"map.viewport","value":{"width":640,"height":480,"operation":"pan","dx":1.,"dy":0.}}}),p);assert_eq!(moved["state"]["map"]["longitude"],90.);}
#[test]fn wrap_mail_pages_all_saved_headers_and_opens_body(){let c=super::mail::Config{endpoint:"https://mail.example.org/jmap",provider:"mail",server_account:"account",mailbox:"inbox"};let f=super::mail::controller(json!({}),&c);let mut state=f["state"].clone();state["route"]=json!("headers");state["active"]=json!({"account":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","provider":"mail"});state["snapshot"]=json!({"items":(0..65).map(|i|json!({"id":format!("e{i}"),"subject":format!("Header {i}"),"from":[]})).collect::<Vec<_>>()});for _ in 0..3{state=super::mail::controller(json!({"state":state,"event":{"action":"mail.next"}}),&c)["state"].clone();}let f=super::mail::controller(json!({"state":state}),&c);assert!(f["body"].as_array().unwrap().iter().any(|n|n["id"]=="mail.open.60"));let body=super::mail::controller(json!({"state":f["state"],"event":{"action":"mail.open.60"}}),&c);assert_eq!(body["effect"]["service"],"http.request");assert!(body["effect"]["args"]["body"].as_str().unwrap().contains("e60"));}

#[test]fn wrap_mail_private_files_delete_requires_confirmation_and_retains_failed_file(){let c=super::mail::Config{endpoint:"https://mail.example.org/jmap",provider:"mail",server_account:"account",mailbox:"inbox"};let mut f=super::mail::controller(json!({"event":{"action":"mail.files"}}),&c);assert_eq!(f["effect"]["service"],"blobs.list");assert_eq!(f["effect"]["args"]["limit"],20);f=super::mail::controller(json!({"state":f["state"],"event":{"action":"mail.files.loaded","reply":{"ok":true,"value":{"items":[{"id":"a".repeat(32),"name":"Saved.eml","size":120,"ready":true}],"next":null}}}}),&c);assert!(f["body"].as_array().unwrap().iter().any(|n|n["id"]=="mail.file.open.0"));f=super::mail::controller(json!({"state":f["state"],"event":{"action":"mail.file.delete.0"}}),&c);assert!(f["effect"].is_null());assert_eq!(f["confirm"]["accept"],"mail.file.delete.accept");f=super::mail::controller(json!({"state":f["state"],"event":{"action":"mail.file.delete.accept"}}),&c);assert_eq!(f["effect"]["service"],"blobs.delete");f=super::mail::controller(json!({"state":f["state"],"event":{"action":"mail.file.deleted","reply":{"ok":false}}}),&c);assert!(f["state"]["delete_file"]["id"].is_string());assert_eq!(f["state"]["files"].as_array().unwrap().len(),1);}

#[test]fn wrap_mail_private_file_page_stays_within_native_widget_budget(){let c=super::mail::Config{endpoint:"https://mail.example.org/jmap",provider:"mail",server_account:"account",mailbox:"inbox"};let f=super::mail::controller(json!({"event":{"action":"mail.files"}}),&c);let f=super::mail::controller(json!({"state":f["state"],"event":{"action":"mail.files.loaded","reply":{"ok":true,"value":{"items":(0..20).map(|i|json!({"id":format!("{i:032x}"),"name":"Saved.eml","ready":true})).collect::<Vec<_>>(),"next":"a".repeat(32)}}}}),&c);assert!(f["body"].as_array().unwrap().len()<100);let next=super::mail::controller(json!({"state":f["state"],"event":{"action":"mail.files.more"}}),&c);assert_eq!(next["effect"]["args"]["after"],"a".repeat(32));assert_eq!(next["effect"]["args"]["limit"],20);}
